// 网关固定窗口限流：每分钟最多 N 次，超过返回 false（注意临界突变缺陷）
class FixedWindowLimiter {
  constructor(limit, windowMs) {
    this.limit = limit;
    this.windowMs = windowMs;
    this.count = 0;
    this.resetAt = Date.now() + windowMs;
  }
  allow() {
    const now = Date.now();
    if (now > this.resetAt) { this.count = 0; this.resetAt = now + this.windowMs; }
    if (this.count >= this.limit) return false;
    this.count++;
    return true;
  }
}

const lim = new FixedWindowLimiter(3, 60000);
console.log([1, 2, 3, 4].map(() => lim.allow()));
